<?php
 namespace Pterodactyl\Services\Dezerx\Ai; class AnthropicProvider implements ChatProvider { private const ENDPOINT = 'https://api.anthropic.com/v1/messages'; private const VERSION = '2023-06-01'; private const MAX_TOKENS = 16000; private const CONTINUATIONS = 2; private bool $autoCache = true; public function __construct( private readonly string $key, private readonly string $model, private readonly int $maxSteps, ) { } public function converse(string $system, array $history, ToolBox $tools): AiReply { $definitions = array_map(fn (array $tool) => [ 'name' => $tool['name'], 'description' => $tool['description'], 'input_schema' => $tool['schema'], ], $tools->definitions()); $messages = array_map(fn (array $turn) => ['role' => $turn['role'], 'content' => $turn['content']], $history); $text = ''; $partial = ''; $finished = false; $continued = 0; for ($step = 0; $step < $this->maxSteps; ++$step) { if ($step > 0 && $tools->outOfTime()) { break; } $choice = $tools->pending() !== [] ? 'none' : 'auto'; $message = $this->send($system, $messages, $definitions, $tools, $choice); $content = (array) ($message['content'] ?? []); $stop = (string) ($message['stop_reason'] ?? ''); $said = []; $calls = []; foreach ($content as $block) { if (($block['type'] ?? '') === 'text') { $said[] = (string) ($block['text'] ?? ''); } elseif (($block['type'] ?? '') === 'tool_use') { $calls[] = $block; } } $raw = implode("\n\n", $said); $said = trim($raw); if ($stop === 'refusal') { $explanation = trim((string) ($message['stop_details']['explanation'] ?? '')); $text = $said !== '' ? $said : ($explanation !== '' ? $explanation : 'The model declined to help with that.'); $finished = true; break; } if ($stop === 'pause_turn') { $messages[] = ['role' => 'assistant', 'content' => $content]; continue; } if ($calls === []) { if ($stop === 'max_tokens' && $said !== '' && $continued < self::CONTINUATIONS) { $partial .= $raw; $messages[] = ['role' => 'assistant', 'content' => $content]; $messages[] = ['role' => 'user', 'content' => 'Continue exactly where you stopped, without repeating anything.']; $continued++; continue; } $text = trim($partial . $raw) ?: $text; $finished = true; break; } if ($said !== '') { $text = $said; } $messages[] = ['role' => 'assistant', 'content' => $content]; $results = []; foreach ($calls as $call) { if ($stop === 'max_tokens') { $result = $tools->invalid((string) ($call['name'] ?? ''), 'That call was cut off by the output limit before it was complete. Make it smaller: change part of a file with edit_file rather than writing all of it.'); } else { $result = $tools->run((string) ($call['name'] ?? ''), is_array($call['input'] ?? null) ? $call['input'] : []); } $block = ['type' => 'tool_result', 'tool_use_id' => (string) ($call['id'] ?? ''), 'content' => $result]; if ($tools->lastFailed()) { $block['is_error'] = true; } $results[] = $block; } $messages[] = ['role' => 'user', 'content' => $results]; } if (!$finished) { $text = $this->wrapUp($system, $messages, $definitions, $tools) ?? $text; } return new AiReply($text, $tools->steps(), !$finished); } private function wrapUp(string $system, array $messages, array $definitions, ToolBox $tools): ?string { $last = array_key_last($messages); if ($last !== null && $messages[$last]['role'] === 'user' && is_array($messages[$last]['content'])) { $messages[$last]['content'][] = ['type' => 'text', 'text' => ToolBox::WRAP_UP]; } else { $messages[] = ['role' => 'user', 'content' => ToolBox::WRAP_UP]; } try { $tools->extendForWrapUp(); $message = $this->send($system, $messages, $definitions, $tools, 'none'); } catch (Stopped $stopped) { throw $stopped; } catch (AiUnavailable) { return null; } $said = []; foreach ((array) ($message['content'] ?? []) as $block) { if (($block['type'] ?? '') === 'text') { $said[] = (string) ($block['text'] ?? ''); } } $said = trim(implode("\n\n", $said)); return $said === '' ? null : $said; } private function send(string $system, array $messages, array $tools, ToolBox $toolbox, string $choice = 'auto'): array { while (true) { $body = [ 'model' => $this->model, 'max_tokens' => self::MAX_TOKENS, 'system' => [['type' => 'text', 'text' => $system, 'cache_control' => ['type' => 'ephemeral']]], 'messages' => $messages, ]; if ($tools !== []) { $body['tools'] = $tools; $body['tool_choice'] = ['type' => $choice]; } if ($this->autoCache) { $body['cache_control'] = ['type' => 'ephemeral']; } $response = ModelHttp::post(self::ENDPOINT, [ 'x-api-key' => $this->key, 'anthropic-version' => self::VERSION, ], $body, $toolbox); if ($response->status() === 400 && $this->autoCache && str_contains(ModelHttp::reason($response), 'cache_control')) { $this->autoCache = false; continue; } if ($response->failed()) { ModelHttp::fail($response, $this->model); } $body = $response->json(); if (!is_array($body) || !is_array($body['content'] ?? null)) { throw new AiUnavailable('The model answered with something this panel could not read.'); } return $body; } } } 